/// The outcome of a [`PermissionPolicy::check`] (or the resolved decision).
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum PermissionDecision {
    /// Run the call unchanged.
    Allow,
    /// Block the call; the reason is surfaced to the model as a tool result.
    Deny {
        /// Human-readable denial reason.
        reason: String,
    },
    /// Ask a human (resolved via [`ApprovalHandler`]; default Deny).
    AskUser {
        /// Prompt shown to the approver.
        prompt: String,
    },
    /// Replace the call's arguments before execution (sanitize).
    Replace {
        /// Replacement JSON arguments.
        args: serde_json::Value,
    },
}

/// Authorizes a tool call. The decision pipeline runs
/// `deny rules › guard rules › allow rules › mode › this policy` (see
/// `control.rs`).
#[async_trait]
pub trait PermissionPolicy<Ctx>: Send + Sync
where
    Ctx: Send + Sync + 'static,
{
    /// Decide whether `tool` may run with `args`.
    async fn check(
        &self,
        ctx: &RunContext<Ctx>,
        tool: &str,
        args: &serde_json::Value,
    ) -> PermissionDecision;
}

/// How a [`DenyRule`] matches a call.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Matcher {
    /// Exact tool name.
    Tool(String),
    /// Any Bash sub-command whose resolved program equals this. Tool-scoped to
    /// the `Bash` tool.
    BashProgram(String),
    /// `Read` tool whose `path` arg matches this glob.
    ReadPath(crate::path_match::PathGlob),
    /// `Edit`/`Write` tool whose `path` arg matches this glob.
    EditPath(crate::path_match::PathGlob),
}

/// A first-class deny rule, evaluated **before** mode — so it overrides even
/// [`PermissionMode::Bypass`].
#[derive(Debug, Clone, PartialEq, Eq)]
    }
}

/// Resolves a [`PermissionDecision::AskUser`] when the driver cannot decide
/// inline. Non-generic — it needs no `Ctx`.
#[async_trait]
pub trait ApprovalHandler: Send + Sync {
    /// Decide an `AskUser` prompt. Returns a narrowed [`ApprovalOutcome`]
    /// (cannot recursively ask).
    async fn decide(&self, tool: &str, prompt: &str, args: &serde_json::Value) -> ApprovalOutcome;
}

/// The narrowed decision an [`ApprovalHandler`] may return.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum ApprovalOutcome {
    /// Allow the call.
    Allow,
    /// Deny the call with a reason.
    Deny {
        /// Human-readable denial reason.
        reason: String,
    },
}

/// The action a tripped [`GuardRule`] takes. Evaluated **before** mode, so it
/// overrides even [`PermissionMode::Bypass`].
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum GuardAction {
    /// Hard-deny with a reason.
    /// Fire on `event` and return a [`HookDecision`].
    async fn on_event(&self, ctx: &RunContext<Ctx>, event: &HookEvent) -> HookDecision;
}

/// A lifecycle event seen by a [`Hook`].
///
/// Variants mirror the Claude Agent SDK's hook taxonomy. Additional
/// variants land with the agent-loop ticket.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum HookEvent {
    /// Fired once at the start of a run.
    OnRunStart,
    /// Fired at the start of each turn.
    OnTurnStart {
        /// Zero-based turn index.
        turn: u32,
    },
    /// Fired just before a tool is invoked.
    PreToolUse {
        /// Tool name.
        tool: String,
        /// JSON arguments about to be passed.
        args: serde_json::Value,
    },
    /// Fired just after a tool returns.
    PostToolUse {
        /// Tool name.
        tool: String,
        /// JSON output the tool produced.
        output: serde_json::Value,
    },
    /// Fired at a handoff from one agent to another.
    OnHandoff {
        /// Outgoing agent name.
        from: String,
        /// Incoming agent name.
        to: String,
    },
    /// Fired once at the end of a run.
    ///
    /// Best-effort: if the run is cancelled while this hook is still running, the
    /// hook may be aborted mid-execution (cancellation tears down the agent
    /// stream, dropping the suspended hook). Consumers needing guaranteed
    /// post-run cleanup must not rely solely on `OnRunComplete`.
    OnRunComplete,
    /// Fired when a subagent sub-run completes — a handoff target, an
    /// agent-as-tool sub-run, or a workflow sub-agent (Sequential/Parallel/Loop).
    OnSubagentStop {
        /// Name of the subagent that completed.
        agent: String,
    },
}

/// A [`Hook`]'s reply to a [`HookEvent`].
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum HookDecision {
    /// Allow the event to proceed unchanged.
