    pub fn ts_nanos_saturating(&self) -> i64 {
        let nanos_i128 = self.ts().as_nanosecond();
        let saturated = if nanos_i128 < 0 { i64::MIN } else { i64::MAX };
        i64::try_from(nanos_i128).unwrap_or(saturated)
    }
